import{_ as a,a as i}from"./chunks/m_qr_ios.BHk-vJJO.js";import{_ as l,o,c as t,aa as n}from"./chunks/framework.BAs_AphD.js";const r="/buildary-help-preview/media/cs/diary/m_android_new.png",s="/buildary-help-preview/media/cs/diary/m_ios_new.png",p="/buildary-help-preview/media/cs/diary/m_prihlas_mail_1.png",d="/buildary-help-preview/media/cs/diary/m_prihlas_azure.png",y=JSON.parse('{"title":"Mobilní aplikace","description":"","frontmatter":{"title":"Mobilní aplikace","wiki":"cs:diary:m_firststeps"},"headers":[],"relativePath":"firstofall/mobile.md","filePath":"firstofall/mobile.md","lastUpdated":1794209661000}'),c={name:"firstofall/mobile.md"};function m(h,e,u,b,v,k){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="mobilni-aplikace" tabindex="-1">Mobilní aplikace <a class="header-anchor" href="#mobilni-aplikace" aria-label="Permalink to &quot;Mobilní aplikace&quot;">​</a></h1><p>Mobilní aplikace Buildary slouží k práci přímo na stavbě: zapisujete a prohlížíte denní záznamy, zakládáte a řešíte úkoly a fotíte. Stavební deník i Management úkolů jsou v jedné aplikaci. Přihlašujete se stejným účtem jako na webu.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/mobilni-aplikace-denik">Psát deník v mobilu</a> v Akademii.</p><h2 id="co-se-dela-jen-na-webu" tabindex="-1">Co se dělá jen na webu <a class="header-anchor" href="#co-se-dela-jen-na-webu" aria-label="Permalink to &quot;Co se dělá jen na webu&quot;">​</a></h2><p>Mobilní aplikace nenahrazuje webovou. Nejdřív si ve <a href="https://app.buildary.online/" target="_blank" rel="noreferrer">webové aplikaci</a> připravte stavbu – tyto věci v mobilu nejdou:</p><ul><li>založení účtu a obnovení zapomenutého hesla,</li><li>založení a nastavení stavby včetně výkresů,</li><li>přidání firem a členů projektového týmu a nastavení kompetencí,</li><li>založení a nastavení stavebních deníků,</li><li>pravidla pro přiřazování Řešitelů a Schvalovatelů úkolů.</li></ul><h2 id="stahnout-aplikaci" tabindex="-1">Stáhnout aplikaci <a class="header-anchor" href="#stahnout-aplikaci" aria-label="Permalink to &quot;Stáhnout aplikaci&quot;">​</a></h2><div class="shots"><figure class="shot" style="--w:300px;"><img src="'+r+'" alt="Buildary.Online v Obchodě Play" loading="lazy"><figcaption><strong>Android</strong> – v Obchodě Play jako <strong>Buildary.Online</strong>, pro Android 10 a novější.</figcaption></figure><figure class="shot" style="--w:140px;"><img src="'+a+'" alt="QR kód ke stažení pro Android" loading="lazy"><figcaption>QR kód pro Android</figcaption></figure></div><div class="shots"><figure class="shot" style="--w:300px;"><img src="'+s+'" alt="Buildary Online v App Store" loading="lazy"><figcaption><strong>iPhone a iPad</strong> – v App Store jako <strong>Buildary Online</strong>, pro iOS 15 a novější.</figcaption></figure><figure class="shot" style="--w:140px;"><img src="'+i+'" alt="QR kód ke stažení pro iOS" loading="lazy"><figcaption>QR kód pro iOS</figcaption></figure></div><p>Pokud se vám aplikace v obchodě nezobrazuje, váš telefon má starší verzi systému, než aplikace potřebuje.</p><h2 id="prihlasit-se" tabindex="-1">Přihlásit se <a class="header-anchor" href="#prihlasit-se" aria-label="Permalink to &quot;Přihlásit se&quot;">​</a></h2><ol><li>Spusťte aplikaci a klepněte na <strong>Přihlásit do aplikace</strong>.</li><li>Otevře se přihlášení <strong>First Account</strong>: <ul><li><strong>e-mailem a heslem</strong> – vyplňte je a klepněte na <strong>Přihlásit</strong>,</li><li><strong>Microsoft účtem</strong> – nic nevyplňujte, klepněte na tlačítko pro přihlášení Microsoft účtem.</li></ul></li><li>Vyberte stavbu ze seznamu staveb, do kterých máte přístup.</li></ol><div class="shots"><figure class="shot" style="--w:180px;"><img src="'+p+'" alt="Přihlášení e-mailem a heslem v mobilní aplikaci" loading="lazy"></figure><figure class="shot" style="--w:180px;"><img src="'+d+'" alt="Přihlášení Microsoft účtem v mobilní aplikaci" loading="lazy"></figure></div><p>Při dalším spuštění se otevře to, s čím jste pracovali naposledy – deník nebo seznam úkolů. Jednou za 30 dní se aplikace zeptá na přihlášení znovu.</p><p>Nemáte ještě účet nebo jste zapomněli heslo? Obojí vyřešíte na webu – viz <a href="/buildary-help-preview/firstofall/access">Registrace a přihlášení</a>. Po několika chybných pokusech se účet dočasně zamkne, viz <a href="/buildary-help-preview/firstofall/loginproblems#ucet-byl-uzamcen">Problémy s přihlášením</a>.</p><h2 id="dalsi-navody-pro-mobil" tabindex="-1">Další návody pro mobil <a class="header-anchor" href="#dalsi-navody-pro-mobil" aria-label="Permalink to &quot;Další návody pro mobil&quot;">​</a></h2><ul><li>Stavební deník: <a href="/buildary-help-preview/diary/m_project_list">Seznam staveb</a>, <a href="/buildary-help-preview/diary/m_dailyentries">Denní záznamy</a>, <a href="/buildary-help-preview/diary/m_signing">Podepisování</a>, <a href="/buildary-help-preview/diary/m_certificate">Certifikát</a>, <a href="/buildary-help-preview/diary/m_offline">Práce bez signálu</a></li><li>Management úkolů: <a href="/buildary-help-preview/tickets/m_task_grid">Úkoly v mobilu</a>, <a href="/buildary-help-preview/tickets/m_task_new">Nový úkol v mobilu</a></li></ul><p>Aplikace se sama přizpůsobí světlému nebo tmavému režimu telefonu.</p>',18)])])}const _=l(c,[["render",m]]);export{y as __pageData,_ as default};
